# Generated from tools/data/rulebooks/cheat.json; run tools/compile-rulebooks.rb.
module GameRoomGames
  class Cheat
    module GeneratedRulebook
      private

      def generated_rule_sections
        [
          rule_section(:aim, GameRoomRules.translate("Getting rid of your cards"),
            GameRoomRules.translate("Be the first to empty your hand. The whole 52-card deck, without jokers, is dealt as evenly as possible to 2\u20138 players. The first player is chosen at random. You see your own hand; everyone can read how many cards each player holds by pressing S."),
            GameRoomRules.translate("In the default game you play one to four cards face down and declare their rank. The first declaration is aces, followed by twos, threes and so on through ten, jack, queen and king, then back to aces. The actual cards may be different: bluffing is a legal part of the game. The number of cards you play is always announced accurately.")),
          rule_section(:turn, GameRoomRules.translate("Preparing a play"),
            GameRoomRules.translate("Use Up and Down to move through your whole hand, or Left and Right to jump between suits. H reads your hand in its current display order. You may choose any of your cards, including cards that do not match the declaration."),
            GameRoomRules.translate("To play one card, select it and press Enter. For a larger packet, mark cards with Shift+Enter; pressing it again removes a card from the packet. P reads the marked cards and Shift+P clears them. When you press Enter, the card under the cursor is added too if it was not marked. Check the final card count and declaration, then choose Play. Escape or Cancel returns to the hand without playing or clearing your packet. The hand\u2019s context menu also offers Play."),
            GameRoomRules.translate("For example, on an ace turn you can select two different cards and declare two aces. Both may be aces, neither may be an ace, or only one may be an ace. Opponents hear the declaration and count, not the hidden card names. Once the reactions finish, the next player declares twos even if someone challenged your aces.")),
          rule_section(:reaction, GameRoomRules.translate("Challenging a declaration"),
            GameRoomRules.translate("After every face-down play, the other players decide in seat order, starting with the next seat. When your decision is due, press K or choose Challenge to question the play. Press Space or choose Do not challenge to pass this decision to the next opponent. This is not a promise that the cards are true and is not the Bluff variant\u2019s pass."),
            GameRoomRules.translate("There is no reaction countdown. Waiting, reading help or leaving the keyboard does not accept the play. Only the player currently asked may respond. The first challenge closes the other reactions. If everyone declines to challenge, the cards stay on the pile and play continues."),
            GameRoomRules.translate("A challenge reveals only the latest packet. If even one of its cards has a different rank, its author takes the whole pile. If every card matches, the challenger takes the whole pile. Earlier hidden cards are not revealed merely because the pile is collected. The required rank and next seat continue normally after either outcome. C repeats the public pile size, last declaration and current decision; T says who must act.")),
          rule_section(:ending, GameRoomRules.translate("Winning"),
            GameRoomRules.translate("Playing your last cards does not immediately win: opponents still get their normal reactions. You win when everyone accepts that play, even if it was a bluff. You also win if a challenge proves your last packet true. If your last bluff is caught, you take the pile and keep playing. The game ends with one winner; the other players receive no points and are not ranked.")),
          rule_section(:variants, GameRoomRules.translate("Choosing a variant"),
            GameRoomRules.translate("Choose Variant when creating the table. Classic: ascending ranks is the default described above. All variants use one deck and the same ordered, untimed reactions."),
            GameRoomRules.translate("- Descending ranks starts with aces, then king, queen, jack, ten and down to two, returning to ace. Challenges do not reset this cycle."),
            GameRoomRules.translate("- Same or neighbouring rank starts with aces. Afterwards choose the previous declared rank or either neighbour. After seven you can declare six, seven or eight; after ace you can declare king, ace or two. King and ace are neighbours in this version. Select the declaration in the play dialog and choose Play to submit the cards together with it."),
            GameRoomRules.translate("- Bluff: fixed pile rank is for 3\u20136 players and adds passing, explained below."),
            GameRoomRules.translate("- Suit: single cards uses a face-up opening and then concealed single cards, explained below.")),
          rule_section(:bluff, GameRoomRules.translate("Bluff: one rank until the pile closes"),
            GameRoomRules.translate("The opener plays one to four cards and chooses any of the thirteen ranks in the play dialog. That rank applies to every later packet on this pile. On your playing turn, add one to four cards or press X to pass until the pile closes. You cannot open an empty pile by passing."),
            GameRoomRules.translate("A pass prevents you from adding more cards to this pile, but you still decide whether to challenge each new packet. Playing another packet does not bring passed players back. If only one player has not passed, that player may keep adding packets; the others still get reactions each time."),
            GameRoomRules.translate("When every player has passed, the pile is set aside face down and the last person who played opens a new pile with any rank. After a correct challenge, the challenger opens; after a wrong challenge, the challenged author opens. Passes are then cleared. A last packet must still survive reactions before its author wins. In this version the entire deck is dealt, and neither jokers nor Force rules are used.")),
          rule_section(:suit, GameRoomRules.translate("Suit: face-up opening and single cards"),
            GameRoomRules.translate("The opener selects a card and presses Enter to confirm a face-up opening. Its actual suit becomes the pile\u2019s suit. This visible card cannot be challenged. Each following player plays one card face down, declaring that same suit; no rank is declared. Shift+Enter cannot build a multi-card packet here."),
            GameRoomRules.translate("Use K or Space when asked about a concealed play. A challenge checks only the suit: a seven and a king of hearts both satisfy a hearts declaration. A wrong suit makes the author collect the pile; a true suit makes the challenger collect it. Whoever collects opens the next pile with any face-up card. If your last card is the face-up opening, you win immediately. A last concealed card must survive reactions as usual.")),
          rule_section(:sound, GameRoomRules.translate("Recognising the game sounds"),
            GameRoomRules.translate("Dealing uses the shuffle sound, and an accepted play uses the card-placement sound whether it is true or a bluff. A challenge has a distinct signal, followed by reveal, outcome and collection sounds. The usual decision cue tells you when to play or react; the usual result cues mark the end. All important information is also spoken, so the game remains playable with optional effects switched off.")),
          rule_section(:controls, GameRoomRules.translate("Cheat keyboard controls"),
            GameRoomRules.translate("Enter: prepare and confirm the current card or packet"),
            GameRoomRules.translate("Shift+Enter: mark or unmark the current card, except in Suit"),
            GameRoomRules.translate("P: read the prepared packet"),
            GameRoomRules.translate("Shift+P: clear the prepared packet"),
            GameRoomRules.translate("K: challenge when it is your reaction"),
            GameRoomRules.translate("Space: decline to challenge this play"),
            GameRoomRules.translate("X: pass until the pile closes in Bluff"),
            GameRoomRules.translate("H: read your own hand"),
            GameRoomRules.translate("T: read who must play or react"),
            GameRoomRules.translate("S: read each player\u2019s card count"),
            GameRoomRules.translate("C: read the public pile and declaration"),
            GameRoomRules.translate("Shift+C: sort by suit"),
            GameRoomRules.translate("Shift+H: sort by rank"),
            GameRoomRules.translate("Shift+M: restore acquisition order"),
            GameRoomRules.translate("Z: move to the next playable card without playing"),
            GameRoomRules.translate("Shift+Z: move to the previous playable card without playing"),
            GameRoomRules.translate("Escape: cancel your current choice"))
        ]
      end

      def localized_rule_sections
        case GameRoomLocalization.primary_language
        when "cs"
          [
            rule_section(:aim, "C\u00EDl hry a rozd\u00E1n\u00ED",
              "Zbavte se v\u0161ech karet jako prvn\u00ED. Cel\u00FD bal\u00ED\u010Dek 52 karet bez \u017Eol\u00EDk\u016F se rozd\u00E1 co nejrovnom\u011Brn\u011Bji mezi 2\u20138 hr\u00E1\u010D\u016F. Za\u010D\u00EDnaj\u00EDc\u00ED hr\u00E1\u010D se losuje. Vid\u00EDte svou ruku; kl\u00E1vesa S p\u0159e\u010Dte po\u010Det karet ka\u017Ed\u00E9ho hr\u00E1\u010De.",
              "Ve v\u00FDchoz\u00ED h\u0159e pokl\u00E1d\u00E1te jednu a\u017E \u010Dty\u0159i karty l\u00EDcem dol\u016F a oznamujete jejich hodnotu. Za\u010D\u00EDn\u00E1 se esy, n\u00E1sleduj\u00ED dvojky, trojky a dal\u0161\u00ED hodnoty a\u017E po des\u00EDtky, kluky, d\u00E1my a kr\u00E1le. Po kr\u00E1l\u00EDch p\u0159ijdou znovu esa. Skute\u010Dn\u00E9 karty mohou b\u00FDt jin\u00E9: blufov\u00E1n\u00ED je dovoleno. Po\u010Det polo\u017Een\u00FDch karet se v\u017Edy oznamuje pravdiv\u011B."),
            rule_section(:turn, "V\u00FDb\u011Br a zahr\u00E1n\u00ED karet",
              "\u0160ipkami nahoru a dol\u016F proch\u00E1z\u00EDte celou ruku, vlevo a vpravo p\u0159ech\u00E1z\u00EDte mezi barvami. H p\u0159e\u010Dte ruku v pr\u00E1v\u011B zobrazen\u00E9m po\u0159ad\u00ED. Vybrat m\u016F\u017Eete kteroukoli vlastn\u00ED kartu, i kdy\u017E neodpov\u00EDd\u00E1 ozn\u00E1men\u00E9 hodnot\u011B.",
              "Jednu kartu p\u0159iprav\u00EDte kl\u00E1vesou Enter. Pro v\u00EDce karet je ozna\u010Dujte pomoc\u00ED Shift+Enter; opakovan\u00FD stisk kartu odebere. P p\u0159e\u010Dte ozna\u010Den\u00E9 karty a Shift+P v\u00FDb\u011Br vyma\u017Ee. Enter p\u0159id\u00E1 i kartu pod kurzorem, pokud dosud ozna\u010Den\u00E1 nebyla. Zkontrolujte kone\u010Dn\u00FD po\u010Det a ozn\u00E1men\u00ED a zvolte Zahr\u00E1t. Escape nebo Zru\u0161it v\u00E1s vr\u00E1t\u00ED do ruky bez zahr\u00E1n\u00ED a ponech\u00E1 p\u0159ipraven\u00FD v\u00FDb\u011Br. Zahr\u00E1n\u00ED je dostupn\u00E9 tak\u00E9 v kontextov\u00E9 nab\u00EDdce ruky.",
              "Nap\u0159\u00EDklad p\u0159i esech m\u016F\u017Eete vybrat dv\u011B r\u016Fzn\u00E9 karty a ozn\u00E1mit dv\u011B esa. Esy mohou b\u00FDt ob\u011B, \u017E\u00E1dn\u00E1 nebo jen jedna. Soupe\u0159i sly\u0161\u00ED po\u010Det a ozn\u00E1menou hodnotu, nikoli n\u00E1zvy skryt\u00FDch karet. Po reakc\u00EDch dal\u0161\u00ED hr\u00E1\u010D oznamuje dvojky, i kdy\u017E n\u011Bkdo va\u0161e esa zkontroloval."),
            rule_section(:reaction, "Kontrola ozn\u00E1men\u00ED",
              "Po ka\u017Ed\u00E9m zakryt\u00E9m zahr\u00E1n\u00ED rozhoduj\u00ED soupe\u0159i postupn\u011B podle m\u00EDst, po\u010D\u00EDnaje n\u00E1sleduj\u00EDc\u00EDm hr\u00E1\u010Dem. Kdy\u017E jste na \u0159ad\u011B s reakc\u00ED, K nebo p\u0159\u00EDkaz Zkontrolovat zpochybn\u00ED posledn\u00ED zahr\u00E1n\u00ED. Mezern\u00EDk nebo Nekontrolovat p\u0159ed\u00E1 rozhodnut\u00ED dal\u0161\u00EDmu soupe\u0159i. Odm\u00EDtnut\u00ED kontroly nepotvrzuje pravdivost karet a nen\u00ED pasov\u00E1n\u00EDm ve variant\u011B Bluff.",
              "Na reakci nen\u00ED \u010Dasov\u00FD limit. Pouh\u00FDm \u010Dek\u00E1n\u00EDm, \u010Dten\u00EDm n\u00E1pov\u011Bdy ani odchodem od kl\u00E1vesnice tah nepotvrd\u00EDte. Odpov\u00EDd\u00E1 jen pr\u00E1v\u011B vyzvan\u00FD hr\u00E1\u010D. Prvn\u00ED kontrola ukon\u010D\u00ED ostatn\u00ED reakce. Pokud nikdo nekontroluje, karty z\u016Fstanou na hrom\u00E1dce a hra pokra\u010Duje.",
              "Odkryje se pouze posledn\u00ED skupina karet. Sta\u010D\u00ED jedin\u00E1 karta jin\u00E9 hodnoty a celou hrom\u00E1dku si vezme jej\u00ED autor. Pokud odpov\u00EDdaj\u00ED v\u0161echny, vezme si ji kontroluj\u00EDc\u00ED. Star\u0161\u00ED zakryt\u00E9 karty se t\u00EDm neodhaluj\u00ED. Po\u0159ad\u00ED m\u00EDst ani sled hodnot se kontrolou nem\u011Bn\u00ED. C p\u0159e\u010Dte velikost hrom\u00E1dky, posledn\u00ED ozn\u00E1men\u00ED a o\u010Dek\u00E1van\u00E9 rozhodnut\u00ED; T \u0159ekne, kdo m\u00E1 jednat."),
            rule_section(:ending, "V\u00EDt\u011Bzstv\u00ED",
              "Odlo\u017Een\u00ED posledn\u00EDch karet je\u0161t\u011B neznamen\u00E1 okam\u017Eitou v\u00FDhru: soupe\u0159i st\u00E1le dostanou reakci. Vyhrajete, pokud v\u0161ichni posledn\u00ED zahr\u00E1n\u00ED p\u0159ijmou, i kdyby \u0161lo o bluf. Vyhrajete tak\u00E9 po neopr\u00E1vn\u011Bn\u00E9 kontrole pravdiv\u00FDch posledn\u00EDch karet. Odhalen\u00FD posledn\u00ED bluf znamen\u00E1 sebr\u00E1n\u00ED hrom\u00E1dky a pokra\u010Dov\u00E1n\u00ED hry. Partie m\u00E1 jedin\u00E9ho v\u00EDt\u011Bze; ostatn\u00EDm se nep\u0159id\u011Bluj\u00ED body ani dal\u0161\u00ED po\u0159ad\u00ED."),
            rule_section(:variants, "Volba varianty",
              "Variantu zvol\u00EDte p\u0159i vytv\u00E1\u0159en\u00ED stolu. V\u00FDchoz\u00ED je Klasick\u00E1: vzestupn\u00E9 hodnoty, popsan\u00E1 v\u00FD\u0161e. V\u0161echny varianty pou\u017E\u00EDvaj\u00ED jeden bal\u00ED\u010Dek a postupn\u00E9 reakce bez \u010Dasov\u00E9ho limitu.",
              "- Sestupn\u00E9 hodnoty za\u010D\u00EDnaj\u00ED esy, potom p\u0159ijdou kr\u00E1lov\u00E9, d\u00E1my, kluci, des\u00EDtky a ni\u017E\u0161\u00ED hodnoty a\u017E po dvojky, n\u00E1sledn\u011B op\u011Bt esa. Kontrola tento sled nerestartuje.",
              "- Stejn\u00E1 nebo sousedn\u00ED hodnota za\u010D\u00EDn\u00E1 esy. Potom vol\u00EDte posledn\u00ED ozn\u00E1menou hodnotu nebo jej\u00EDho souseda. Po sedmi\u010Dk\u00E1ch lze ozn\u00E1mit \u0161estky, sedmi\u010Dky \u010Di osmi\u010Dky; po esech kr\u00E1le, esa nebo dvojky. Kr\u00E1l a eso jsou v t\u00E9to verzi soused\u00E9. Ozn\u00E1men\u00ED vyberte v dialogu zahr\u00E1n\u00ED a ode\u0161lete je spole\u010Dn\u011B s kartami volbou Zahr\u00E1t.",
              "- Bluff: pevn\u00E1 hodnota hrom\u00E1dky je pro 3\u20136 hr\u00E1\u010D\u016F a dovoluje pasov\u00E1n\u00ED, popsan\u00E9 n\u00ED\u017Ee.",
              "- Barva: jednotliv\u00E9 karty pou\u017E\u00EDv\u00E1 odkryt\u00E9 zah\u00E1jen\u00ED a potom jednotliv\u00E9 zakryt\u00E9 karty."),
            rule_section(:bluff, "Bluff: jedna hodnota do uzav\u0159en\u00ED hrom\u00E1dky",
              "Zahajuj\u00EDc\u00ED zahraje jednu a\u017E \u010Dty\u0159i karty a v dialogu vybere libovolnou ze t\u0159in\u00E1cti hodnot. Ta plat\u00ED pro v\u0161echny dal\u0161\u00ED skupiny na t\u00E9to hrom\u00E1dce. Ve sv\u00E9m tahu m\u016F\u017Eete p\u0159ilo\u017Eit jednu a\u017E \u010Dty\u0159i karty, nebo kl\u00E1vesou X pasovat do uzav\u0159en\u00ED hrom\u00E1dky. Pr\u00E1zdnou hrom\u00E1dku nelze zah\u00E1jit pasem.",
              "Po pasu u\u017E na tuto hrom\u00E1dku nep\u0159ikl\u00E1d\u00E1te, ale st\u00E1le m\u016F\u017Eete kontrolovat ka\u017Ed\u00E9 nov\u00E9 zahr\u00E1n\u00ED. Dal\u0161\u00ED zahr\u00E1n\u00ED nevrac\u00ED pr\u00E1vo p\u0159ikl\u00E1dat hr\u00E1\u010D\u016Fm, kte\u0159\u00ED u\u017E pasovali. Zb\u00FDv\u00E1-li jedin\u00FD hr\u00E1\u010D bez pasu, m\u016F\u017Ee p\u0159ikl\u00E1dat opakovan\u011B a ostatn\u00ED poka\u017Ed\u00E9 rozhodnou, zda nov\u00E9 zahr\u00E1n\u00ED zkontroluj\u00ED.",
              "Jakmile pasuj\u00ED v\u0161ichni, hrom\u00E1dka se odlo\u017E\u00ED zakryt\u00E1 mimo partii a posledn\u00ED p\u0159ikl\u00E1daj\u00EDc\u00ED za\u010Dne novou s libovolnou hodnotou. Po spr\u00E1vn\u00E9 kontrole zahajuje kontroluj\u00EDc\u00ED, po chybn\u00E9 autor kontrolovan\u00E9ho zahr\u00E1n\u00ED. Pasy se vyma\u017Eou. I posledn\u00ED skupina karet mus\u00ED proj\u00EDt reakcemi, ne\u017E hr\u00E1\u010D vyhraje. Tato verze rozd\u00E1v\u00E1 cel\u00FD bal\u00ED\u010Dek a nepou\u017E\u00EDv\u00E1 \u017Eol\u00EDky ani pravidla Force."),
            rule_section(:suit, "Barva: odkryt\u00E9 zah\u00E1jen\u00ED",
              "Zahajuj\u00EDc\u00ED vybere kartu a Enterem potvrd\u00ED jej\u00ED odkryt\u00E9 vylo\u017Een\u00ED. Jej\u00ED skute\u010Dn\u00E1 barva ur\u010D\u00ED barvu hrom\u00E1dky. Tuto viditelnou kartu nelze kontrolovat. Dal\u0161\u00ED hr\u00E1\u010Di p\u0159ikl\u00E1daj\u00ED po jedn\u00E9 zakryt\u00E9 kart\u011B a hl\u00E1s\u00ED stejnou barvu; hodnotu neoznamuj\u00ED. Shift+Enter zde nevytv\u00E1\u0159\u00ED skupinu v\u00EDce karet.",
              "P\u0159i reakci na zakrytou kartu pou\u017Eijte K nebo mezern\u00EDk. Kontroluje se jen barva: srdcov\u00E1 sedmi\u010Dka i srdcov\u00FD kr\u00E1l odpov\u00EDdaj\u00ED hl\u00E1\u0161en\u00FDm srdc\u00EDm. Za jinou barvu bere hrom\u00E1dku autor, za kontrolu pravdiv\u00E9 barvy kontroluj\u00EDc\u00ED. Ten, kdo hrom\u00E1dku sebere, zah\u00E1j\u00ED dal\u0161\u00ED libovolnou odkrytou kartou. Je-li odkryt\u00E9 zah\u00E1jen\u00ED va\u0161\u00ED posledn\u00ED kartou, vyhrajete ihned. Posledn\u00ED zakryt\u00E1 karta vy\u017Eaduje obvykl\u00E9 reakce."),
            rule_section(:sound, "Zvuky hry",
              "Rozd\u00E1n\u00ED doprov\u00E1z\u00ED m\u00EDch\u00E1n\u00ED a p\u0159ijat\u00E9 zahr\u00E1n\u00ED zvuk polo\u017Een\u00FDch karet, stejn\u00FD p\u0159i pravd\u011B i blufu. Kontrola m\u00E1 samostatn\u00FD sign\u00E1l, potom n\u00E1sleduje odkryt\u00ED, v\u00FDsledek kontroly a sebr\u00E1n\u00ED karet. Obvykl\u00FD sign\u00E1l rozhodnut\u00ED ozn\u00E1m\u00ED v\u00E1\u0161 tah nebo reakci a z\u00E1v\u011Bre\u010Dn\u00E9 zvuky konec partie. D\u016Fle\u017Eit\u00E9 informace se tak\u00E9 vyslovuj\u00ED, tak\u017Ee lze hr\u00E1t i s vypnut\u00FDmi voliteln\u00FDmi efekty."),
            rule_section(:controls, "P\u0159ehled kl\u00E1ves",
              "Enter: p\u0159ipravte a potvr\u010Fte kartu nebo skupinu",
              "Shift+Enter: ozna\u010Dte nebo odzna\u010Dte kartu, krom\u011B varianty Barva",
              "P: p\u0159e\u010Dt\u011Bte p\u0159ipraven\u00E9 karty",
              "Shift+P: vyma\u017Ete p\u0159ipraven\u00FD v\u00FDb\u011Br",
              "K: zkontrolujte zahr\u00E1n\u00ED p\u0159i sv\u00E9 reakci",
              "Mezern\u00EDk: odm\u00EDtn\u011Bte kontrolu tohoto zahr\u00E1n\u00ED",
              "X: pasujte do uzav\u0159en\u00ED hrom\u00E1dky ve variant\u011B Bluff",
              "H: p\u0159e\u010Dt\u011Bte svou ruku",
              "T: zjist\u011Bte, kdo m\u00E1 hr\u00E1t nebo reagovat",
              "S: p\u0159e\u010Dt\u011Bte po\u010Dty karet hr\u00E1\u010D\u016F",
              "C: p\u0159e\u010Dt\u011Bte ve\u0159ejn\u00FD stav hrom\u00E1dky a ozn\u00E1men\u00ED",
              "Shift+C: se\u0159a\u010Fte podle barvy",
              "Shift+H: se\u0159a\u010Fte podle hodnoty",
              "Shift+M: obnovte po\u0159ad\u00ED z\u00EDsk\u00E1n\u00ED",
              "Z: p\u0159ejd\u011Bte na dal\u0161\u00ED hratelnou kartu bez zahr\u00E1n\u00ED",
              "Shift+Z: p\u0159ejd\u011Bte na p\u0159edchoz\u00ED hratelnou kartu bez zahr\u00E1n\u00ED",
              "Escape: zru\u0161te aktu\u00E1ln\u00ED v\u00FDb\u011Br")
          ]
        when "en"
          [
            rule_section(:aim, "Getting rid of your cards",
              "Be the first to empty your hand. The whole 52-card deck, without jokers, is dealt as evenly as possible to 2\u20138 players. The first player is chosen at random. You see your own hand; everyone can read how many cards each player holds by pressing S.",
              "In the default game you play one to four cards face down and declare their rank. The first declaration is aces, followed by twos, threes and so on through ten, jack, queen and king, then back to aces. The actual cards may be different: bluffing is a legal part of the game. The number of cards you play is always announced accurately."),
            rule_section(:turn, "Preparing a play",
              "Use Up and Down to move through your whole hand, or Left and Right to jump between suits. H reads your hand in its current display order. You may choose any of your cards, including cards that do not match the declaration.",
              "To play one card, select it and press Enter. For a larger packet, mark cards with Shift+Enter; pressing it again removes a card from the packet. P reads the marked cards and Shift+P clears them. When you press Enter, the card under the cursor is added too if it was not marked. Check the final card count and declaration, then choose Play. Escape or Cancel returns to the hand without playing or clearing your packet. The hand\u2019s context menu also offers Play.",
              "For example, on an ace turn you can select two different cards and declare two aces. Both may be aces, neither may be an ace, or only one may be an ace. Opponents hear the declaration and count, not the hidden card names. Once the reactions finish, the next player declares twos even if someone challenged your aces."),
            rule_section(:reaction, "Challenging a declaration",
              "After every face-down play, the other players decide in seat order, starting with the next seat. When your decision is due, press K or choose Challenge to question the play. Press Space or choose Do not challenge to pass this decision to the next opponent. This is not a promise that the cards are true and is not the Bluff variant\u2019s pass.",
              "There is no reaction countdown. Waiting, reading help or leaving the keyboard does not accept the play. Only the player currently asked may respond. The first challenge closes the other reactions. If everyone declines to challenge, the cards stay on the pile and play continues.",
              "A challenge reveals only the latest packet. If even one of its cards has a different rank, its author takes the whole pile. If every card matches, the challenger takes the whole pile. Earlier hidden cards are not revealed merely because the pile is collected. The required rank and next seat continue normally after either outcome. C repeats the public pile size, last declaration and current decision; T says who must act."),
            rule_section(:ending, "Winning",
              "Playing your last cards does not immediately win: opponents still get their normal reactions. You win when everyone accepts that play, even if it was a bluff. You also win if a challenge proves your last packet true. If your last bluff is caught, you take the pile and keep playing. The game ends with one winner; the other players receive no points and are not ranked."),
            rule_section(:variants, "Choosing a variant",
              "Choose Variant when creating the table. Classic: ascending ranks is the default described above. All variants use one deck and the same ordered, untimed reactions.",
              "- Descending ranks starts with aces, then king, queen, jack, ten and down to two, returning to ace. Challenges do not reset this cycle.",
              "- Same or neighbouring rank starts with aces. Afterwards choose the previous declared rank or either neighbour. After seven you can declare six, seven or eight; after ace you can declare king, ace or two. King and ace are neighbours in this version. Select the declaration in the play dialog and choose Play to submit the cards together with it.",
              "- Bluff: fixed pile rank is for 3\u20136 players and adds passing, explained below.",
              "- Suit: single cards uses a face-up opening and then concealed single cards, explained below."),
            rule_section(:bluff, "Bluff: one rank until the pile closes",
              "The opener plays one to four cards and chooses any of the thirteen ranks in the play dialog. That rank applies to every later packet on this pile. On your playing turn, add one to four cards or press X to pass until the pile closes. You cannot open an empty pile by passing.",
              "A pass prevents you from adding more cards to this pile, but you still decide whether to challenge each new packet. Playing another packet does not bring passed players back. If only one player has not passed, that player may keep adding packets; the others still get reactions each time.",
              "When every player has passed, the pile is set aside face down and the last person who played opens a new pile with any rank. After a correct challenge, the challenger opens; after a wrong challenge, the challenged author opens. Passes are then cleared. A last packet must still survive reactions before its author wins. In this version the entire deck is dealt, and neither jokers nor Force rules are used."),
            rule_section(:suit, "Suit: face-up opening and single cards",
              "The opener selects a card and presses Enter to confirm a face-up opening. Its actual suit becomes the pile\u2019s suit. This visible card cannot be challenged. Each following player plays one card face down, declaring that same suit; no rank is declared. Shift+Enter cannot build a multi-card packet here.",
              "Use K or Space when asked about a concealed play. A challenge checks only the suit: a seven and a king of hearts both satisfy a hearts declaration. A wrong suit makes the author collect the pile; a true suit makes the challenger collect it. Whoever collects opens the next pile with any face-up card. If your last card is the face-up opening, you win immediately. A last concealed card must survive reactions as usual."),
            rule_section(:sound, "Recognising the game sounds",
              "Dealing uses the shuffle sound, and an accepted play uses the card-placement sound whether it is true or a bluff. A challenge has a distinct signal, followed by reveal, outcome and collection sounds. The usual decision cue tells you when to play or react; the usual result cues mark the end. All important information is also spoken, so the game remains playable with optional effects switched off."),
            rule_section(:controls, "Cheat keyboard controls",
              "Enter: prepare and confirm the current card or packet",
              "Shift+Enter: mark or unmark the current card, except in Suit",
              "P: read the prepared packet",
              "Shift+P: clear the prepared packet",
              "K: challenge when it is your reaction",
              "Space: decline to challenge this play",
              "X: pass until the pile closes in Bluff",
              "H: read your own hand",
              "T: read who must play or react",
              "S: read each player\u2019s card count",
              "C: read the public pile and declaration",
              "Shift+C: sort by suit",
              "Shift+H: sort by rank",
              "Shift+M: restore acquisition order",
              "Z: move to the next playable card without playing",
              "Shift+Z: move to the previous playable card without playing",
              "Escape: cancel your current choice")
          ]
        when "es"
          [
            rule_section(:aim, "Objetivo y reparto",
              "S\u00E9 la primera persona en quedarte sin cartas. Se reparte toda la baraja de 52 cartas, sin comodines, lo m\u00E1s equitativamente posible entre 2 y 8 jugadores. Se sortea qui\u00E9n empieza. Solo ves tu mano; S lee cu\u00E1ntas cartas tiene cada participante.",
              "En la variante predeterminada juegas de una a cuatro cartas boca abajo y declaras su valor. La primera declaraci\u00F3n es ases; siguen doses, treses y los dem\u00E1s valores hasta diez, jotas, reinas y reyes. Despu\u00E9s de los reyes vuelven los ases. Las cartas reales pueden ser distintas: se permite mentir. La cantidad de cartas jugadas siempre se anuncia correctamente."),
            rule_section(:turn, "Preparar una jugada",
              "Recorre toda tu mano con las flechas arriba y abajo, o cambia de palo con izquierda y derecha. H lee la mano en el orden mostrado. Puedes elegir cualquier carta propia, aunque no coincida con la declaraci\u00F3n.",
              "Para preparar una sola carta, sit\u00FAate en ella y pulsa Enter. Para un grupo, marca cartas con Shift+Enter; al repetirlo quitas la carta de la selecci\u00F3n. P lee las cartas marcadas y Shift+P borra la selecci\u00F3n. Enter a\u00F1ade tambi\u00E9n la carta situada bajo el cursor si no estaba marcada. Comprueba la cantidad final y la declaraci\u00F3n y elige Jugar. Escape o Cancelar vuelve a la mano sin jugar ni borrar el grupo. El men\u00FA contextual de la mano tambi\u00E9n ofrece Jugar.",
              "Por ejemplo, en un turno de ases puedes seleccionar dos cartas distintas y declarar dos ases. Ambas pueden ser ases, ninguna o solo una. Los rivales oyen la declaraci\u00F3n y la cantidad, pero no los nombres de las cartas ocultas. Tras las reacciones, el siguiente jugador declara doses, aunque alguien haya comprobado tus ases."),
            rule_section(:reaction, "Comprobar una declaraci\u00F3n",
              "Despu\u00E9s de cada jugada boca abajo, los rivales deciden por orden de asiento, empezando por el siguiente. Cuando te corresponda reaccionar, K o Comprobar cuestiona la jugada. Espacio o No comprobar pasa la decisi\u00F3n al siguiente rival. No comprobar no garantiza que las cartas sean verdaderas ni equivale a pasar en la variante Bluff.",
              "No hay l\u00EDmite de tiempo para reaccionar. La jugada no se da por aceptada por esperar, consultar la ayuda o alejarse del teclado. Solo responde la persona indicada. La primera comprobaci\u00F3n cierra las dem\u00E1s reacciones. Si nadie comprueba, las cartas quedan en el mont\u00F3n y contin\u00FAa el juego.",
              "Solo se descubre el \u00FAltimo grupo. Si una sola carta tiene otro valor, quien lo jug\u00F3 recoge todo el mont\u00F3n. Si todas coinciden, lo recoge quien comprob\u00F3. Las cartas ocultas anteriores no se revelan por recogerlas. El orden de asientos y el ciclo de valores contin\u00FAan tras ambos resultados. C repite el tama\u00F1o del mont\u00F3n, la \u00FAltima declaraci\u00F3n y la decisi\u00F3n pendiente; T dice qui\u00E9n debe actuar."),
            rule_section(:ending, "Ganar la partida",
              "Jugar tus \u00FAltimas cartas no te da la victoria de inmediato: los rivales a\u00FAn pueden reaccionar. Ganas si todos aceptan esa jugada, aunque fuera mentira. Tambi\u00E9n ganas si una comprobaci\u00F3n demuestra que tu \u00FAltimo grupo era verdadero. Si descubren tu \u00FAltimo farol, recoges el mont\u00F3n y sigues jugando. Hay una sola persona ganadora; las dem\u00E1s no reciben puntos ni una clasificaci\u00F3n."),
            rule_section(:variants, "Elegir una variante",
              "Elige Variante al crear la mesa. Cl\u00E1sica: valores ascendentes es la opci\u00F3n predeterminada explicada arriba. Todas las variantes usan una baraja y reacciones sucesivas sin l\u00EDmite de tiempo.",
              "- Valores descendentes empieza por ases, despu\u00E9s reyes, reinas, jotas, dieces y los valores inferiores hasta doses; luego vuelve a ases. Una comprobaci\u00F3n no reinicia el ciclo.",
              "- Mismo valor o adyacente empieza por ases. Despu\u00E9s eliges el \u00FAltimo valor declarado o uno de sus vecinos. Tras sietes puedes declarar seises, sietes u ochos; tras ases, reyes, ases o doses. Rey y as son adyacentes en esta versi\u00F3n. Elige la declaraci\u00F3n en el di\u00E1logo de la jugada y confirma Jugar para enviarla con las cartas.",
              "- Bluff: valor fijo del mont\u00F3n admite de 3 a 6 jugadores y permite pasar, como se explica abajo.",
              "- Palo: cartas individuales empieza con una carta descubierta y contin\u00FAa con cartas individuales boca abajo."),
            rule_section(:bluff, "Bluff: un valor hasta cerrar el mont\u00F3n",
              "Quien abre juega de una a cuatro cartas y elige cualquiera de los trece valores en el di\u00E1logo. Ese valor rige para todos los grupos posteriores de este mont\u00F3n. En tu turno de juego puedes a\u00F1adir de una a cuatro cartas o pulsar X para pasar hasta que se cierre el mont\u00F3n. No puedes abrir un mont\u00F3n vac\u00EDo pasando.",
              "Despu\u00E9s de pasar ya no puedes a\u00F1adir cartas a ese mont\u00F3n, pero sigues pudiendo comprobar cada nuevo grupo. Una nueva jugada no devuelve el derecho a a\u00F1adir a quienes pasaron. Si queda una sola persona sin pasar, puede a\u00F1adir grupos repetidamente; las dem\u00E1s vuelven a decidir si comprueban cada jugada cada vez.",
              "Cuando todos han pasado, el mont\u00F3n se aparta boca abajo de la partida y quien jug\u00F3 por \u00FAltima vez abre otro con cualquier valor. Tras una comprobaci\u00F3n acertada abre quien comprob\u00F3; tras una equivocada, quien hizo la jugada comprobada. Se borran los pases. El \u00FAltimo grupo tambi\u00E9n debe superar las reacciones antes de dar la victoria. Esta versi\u00F3n reparte toda la baraja y no usa comodines ni reglas Force."),
            rule_section(:suit, "Palo: apertura descubierta",
              "Quien abre selecciona una carta y confirma con Enter que la juega boca arriba. Su palo real fija el palo del mont\u00F3n. Esa carta visible no se puede comprobar. Las siguientes personas juegan una sola carta boca abajo y declaran el mismo palo, sin declarar valor. Shift+Enter no prepara grupos de varias cartas aqu\u00ED.",
              "Cuando te corresponda reaccionar, usa K o Espacio. Solo se comprueba el palo: un siete y un rey de corazones cumplen por igual una declaraci\u00F3n de corazones. Con un palo falso recoge quien jug\u00F3; con uno verdadero, quien comprob\u00F3. Quien recoge abre el siguiente mont\u00F3n con cualquier carta descubierta. Si tu \u00FAltima carta es esa apertura descubierta, ganas inmediatamente. Una \u00FAltima carta oculta requiere las reacciones habituales."),
            rule_section(:sound, "Sonidos de la partida",
              "El reparto usa el sonido de barajar y una jugada aceptada el de colocar cartas, igual para una verdad y un farol. Una se\u00F1al distingue la comprobaci\u00F3n; despu\u00E9s se oyen el descubrimiento, el resultado y la recogida. La se\u00F1al habitual de decisi\u00F3n avisa de tu turno o reacci\u00F3n, y los efectos de resultado marcan el final. La informaci\u00F3n importante tambi\u00E9n se anuncia por voz, por lo que puedes jugar con los efectos opcionales desactivados."),
            rule_section(:controls, "Referencia de teclas",
              "Enter: prepara y confirma la carta o el grupo actual",
              "Shift+Enter: marca o desmarca la carta, salvo en Palo",
              "P: lee el grupo preparado",
              "Shift+P: borra el grupo preparado",
              "K: comprueba la jugada durante tu reacci\u00F3n",
              "Espacio: decide no comprobar esta jugada",
              "X: pasa hasta que se cierre el mont\u00F3n en Bluff",
              "H: lee tu propia mano",
              "T: anuncia qui\u00E9n debe jugar o reaccionar",
              "S: lee cu\u00E1ntas cartas tiene cada jugador",
              "C: lee el mont\u00F3n p\u00FAblico y la declaraci\u00F3n",
              "Shift+C: ordena por palo",
              "Shift+H: ordena por valor",
              "Shift+M: restaura el orden de recepci\u00F3n",
              "Z: pasa a la siguiente carta jugable sin jugar",
              "Shift+Z: pasa a la carta jugable anterior sin jugar",
              "Escape: cancela la selecci\u00F3n actual")
          ]
        when "pl"
          [
            rule_section(:aim, "Cel gry i rozdanie",
              "Pozb\u0105d\u017A si\u0119 wszystkich kart jako pierwszy. Ca\u0142a talia 52 kart bez joker\u00F3w jest rozdawana mo\u017Cliwie r\u00F3wno mi\u0119dzy 2\u20138 graczy. Rozpoczynaj\u0105cy jest losowany. Widzisz w\u0142asn\u0105 r\u0119k\u0119, a pod S mo\u017Cesz sprawdzi\u0107 jawn\u0105 liczb\u0119 kart ka\u017Cdego uczestnika.",
              "W domy\u015Blnym wariancie wyk\u0142adasz od jednej do czterech zakrytych kart i deklarujesz ich warto\u015B\u0107. Pierwsza osoba deklaruje asy, nast\u0119pna dw\u00F3jki, potem tr\u00F3jki i tak dalej do dziesi\u0105tek, walet\u00F3w, dam i kr\u00F3li. Po kr\u00F3lach zn\u00F3w przychodz\u0105 asy. Twoje karty mog\u0105 mie\u0107 inn\u0105 warto\u015B\u0107: blef jest dozwolony. Liczba wyk\u0142adanych kart zawsze jest podawana zgodnie z prawd\u0105."),
            rule_section(:turn, "Wybieranie i zagrywanie kart",
              "Strza\u0142kami w g\u00F3r\u0119 i w d\u00F3\u0142 przechodzisz przez ca\u0142\u0105 r\u0119k\u0119, a w lewo i w prawo przeskakujesz mi\u0119dzy kolorami. H odczytuje r\u0119k\u0119 w aktualnej kolejno\u015Bci wy\u015Bwietlania. Mo\u017Cesz wybra\u0107 dowoln\u0105 w\u0142asn\u0105 kart\u0119, tak\u017Ce niepasuj\u0105c\u0105 do deklaracji.",
              "Aby zagra\u0107 jedn\u0105 kart\u0119, ustaw na niej kursor i naci\u015Bnij Enter. Wi\u0119kszy pakiet przygotujesz, zaznaczaj\u0105c karty przez Shift+Enter; ponowne u\u017Cycie usuwa kart\u0119 z pakietu. P odczytuje zaznaczenie, a Shift+P je czy\u015Bci. Po Enter do pakietu dochodzi r\u00F3wnie\u017C karta pod kursorem, je\u015Bli nie by\u0142a zaznaczona. Sprawd\u017A ko\u0144cow\u0105 liczb\u0119 kart i deklaracj\u0119, po czym wybierz Zagraj. Escape lub Anuluj wraca do r\u0119ki bez zagrania i zachowuje przygotowany pakiet. Zagra\u0107 mo\u017Cesz r\u00F3wnie\u017C z menu kontekstowego r\u0119ki.",
              "Przyk\u0142adowo, gdy trzeba deklarowa\u0107 asy, mo\u017Cesz wybra\u0107 dwie r\u00F3\u017Cne karty i og\u0142osi\u0107 dwa asy. Mo\u017Cesz wy\u0142o\u017Cy\u0107 dwa asy, tylko jednego asa albo same karty o innych warto\u015Bciach. Przeciwnicy poznaj\u0105 deklaracj\u0119 i liczb\u0119, ale nie nazwy zakrytych kart. Po reakcjach nast\u0119pny gracz deklaruje dw\u00F3jki, r\u00F3wnie\u017C wtedy, gdy twoje asy zosta\u0142y sprawdzone."),
            rule_section(:reaction, "Sprawdzanie deklaracji",
              "Po ka\u017Cdym zakrytym zagraniu przeciwnicy podejmuj\u0105 decyzj\u0119 kolejno wed\u0142ug miejsc, zaczynaj\u0105c od nast\u0119pnego po zagrywaj\u0105cym. Gdy przyjdzie twoja kolej na reakcj\u0119, K lub polecenie Sprawdzam kwestionuje zagranie. Spacja albo Nie sprawdzam przekazuje decyzj\u0119 nast\u0119pnej osobie. Odmowa sprawdzenia nie oznacza zapewnienia, \u017Ce karty s\u0105 prawdziwe, ani pasa stosowanego w wariancie Bluff.",
              "Na reakcj\u0119 nie ma limitu czasu. Czekanie, czytanie pomocy lub odej\u015Bcie od klawiatury nie zatwierdza zagrania. Odpowiada tylko wskazana osoba. Pierwsze sprawdzenie zamyka pozosta\u0142e reakcje. Je\u015Bli nikt nie sprawdzi, karty pozostaj\u0105 na stosie i gra toczy si\u0119 dalej.",
              "Sprawdzenie odkrywa tylko ostatni pakiet. Je\u015Bli cho\u0107 jedna jego karta ma inn\u0105 warto\u015B\u0107 ni\u017C deklarowana, ca\u0142y stos bierze autor zagrania. Je\u017Celi wszystkie karty pasuj\u0105, stos bierze sprawdzaj\u0105cy. Wcze\u015Bniejsze zakryte karty nie s\u0105 przy tym automatycznie ujawniane. Po obu rozstrzygni\u0119ciach kolejno\u015B\u0107 miejsc i cykl warto\u015Bci pozostaj\u0105 bez zmian. C odczytuje rozmiar stosu, ostatni\u0105 deklaracj\u0119 i oczekiwan\u0105 decyzj\u0119, a T m\u00F3wi, kto ma dzia\u0142a\u0107."),
            rule_section(:ending, "Zako\u0144czenie partii",
              "Wy\u0142o\u017Cenie ostatnich kart nie daje od razu zwyci\u0119stwa: przeciwnicy nadal mog\u0105 je sprawdzi\u0107. Wygrywasz, gdy wszyscy zaakceptuj\u0105 ten ruch, nawet je\u015Bli by\u0142 blefem. Wygrywasz tak\u017Ce po nies\u0142usznym sprawdzeniu prawdziwego ostatniego pakietu. Gdy ostatni blef zostanie wykryty, zbierasz stos i grasz dalej. Partia ma jednego zwyci\u0119zc\u0119; pozostali nie otrzymuj\u0105 punkt\u00F3w ani dodatkowych miejsc."),
            rule_section(:variants, "Wyb\u00F3r wariantu",
              "Wariant wybierasz przy tworzeniu sto\u0142u. Domy\u015Blna gra to Klasyczny: warto\u015Bci rosn\u0105co, opisany powy\u017Cej. Ka\u017Cdy profil u\u017Cywa jednej talii i kolejnych reakcji bez ograniczenia czasu.",
              "- Warto\u015Bci malej\u0105co: po asach deklaruje si\u0119 kr\u00F3le, damy, walety, dziesi\u0105tki i kolejne ni\u017Csze warto\u015Bci do dw\u00F3jek, a potem zn\u00F3w asy. Sprawdzenie nie rozpoczyna cyklu od nowa.",
              "- Ta sama lub s\u0105siednia warto\u015B\u0107: pierwsza deklaracja to asy. Potem wybierasz poprzednio zadeklarowan\u0105 warto\u015B\u0107 lub jednego z jej s\u0105siad\u00F3w. Po si\u00F3demkach wolno zadeklarowa\u0107 sz\u00F3stki, si\u00F3demki albo \u00F3semki; po asach kr\u00F3le, asy albo dw\u00F3jki. W tej wersji kr\u00F3l s\u0105siaduje z asem. Wybierz deklaracj\u0119 w oknie zagrania i potwierd\u017A Zagraj, aby wys\u0142a\u0107 j\u0105 razem z kartami.",
              "- Bluff: sta\u0142a warto\u015B\u0107 stosu dopuszcza 3\u20136 graczy i dodaje pasowanie opisane ni\u017Cej.",
              "- Na kolor: pojedyncze karty zaczyna si\u0119 od odkrytej karty, a dalsza gra polega na zakrytym dok\u0142adaniu pojedynczych kart."),
            rule_section(:bluff, "Bluff: jedna warto\u015B\u0107 do zamkni\u0119cia stosu",
              "Otwieraj\u0105cy wyk\u0142ada od jednej do czterech kart i wybiera w oknie zagrania dowoln\u0105 z trzynastu warto\u015Bci. Obowi\u0105zuje ona dla wszystkich kolejnych pakiet\u00F3w na tym stosie. W swojej turze dok\u0142adania mo\u017Cesz do\u0142o\u017Cy\u0107 od jednej do czterech kart albo nacisn\u0105\u0107 X, aby spasowa\u0107 do ko\u0144ca stosu. Pustego stosu nie wolno otworzy\u0107 pasem.",
              "Po pasie nie mo\u017Cesz ju\u017C dok\u0142ada\u0107 do tego stosu, lecz nadal decydujesz o sprawdzaniu nowych pakiet\u00F3w. Kolejne zagranie nie przywraca prawa dok\u0142adania osobom, kt\u00F3re spasowa\u0142y. Gdy pozostanie tylko jeden gracz bez pasa, mo\u017Ce on dok\u0142ada\u0107 nast\u0119pne pakiety, a pozostali za ka\u017Cdym razem otrzymuj\u0105 reakcj\u0119.",
              "Kiedy spasuj\u0105 wszyscy, stos jest odk\u0142adany zakryty poza parti\u0119, a ostatni zagrywaj\u0105cy otwiera nowy dowoln\u0105 warto\u015Bci\u0105. Po trafnym sprawdzeniu otwiera sprawdzaj\u0105cy; po nietrafnym autor sprawdzonego ruchu. Pasy s\u0105 wtedy zerowane. Ostatni pakiet nadal musi przej\u015B\u0107 przez reakcje, zanim jego autor wygra. W tej wersji rozdaje si\u0119 ca\u0142\u0105 tali\u0119; nie u\u017Cywa si\u0119 joker\u00F3w ani regu\u0142 Force."),
            rule_section(:suit, "Na kolor: odkryte otwarcie i pojedyncze karty",
              "Otwieraj\u0105cy wybiera kart\u0119 i potwierdza Enterem jej jawne wy\u0142o\u017Cenie. Rzeczywisty kolor tej karty ustala kolor stosu. Odkrytego otwarcia nie mo\u017Cna sprawdza\u0107. Nast\u0119pne osoby dok\u0142adaj\u0105 po jednej zakrytej karcie, deklaruj\u0105c ten sam kolor; nie deklaruj\u0105 warto\u015Bci. Shift+Enter nie tworzy tu wielokartowego pakietu.",
              "Gdy przyjdzie twoja kolej na decyzj\u0119 o zakrytym zagraniu, u\u017Cyj K lub Spacji. Sprawdzenie dotyczy wy\u0142\u0105cznie koloru: si\u00F3demka i kr\u00F3l kier jednakowo pasuj\u0105 do deklaracji kier. Za b\u0142\u0119dny kolor stos bierze zagrywaj\u0105cy, a za sprawdzenie prawdziwego koloru sprawdzaj\u0105cy. Osoba, kt\u00F3ra zebra\u0142a stos, otwiera nast\u0119pny dowoln\u0105 odkryt\u0105 kart\u0105. Je\u015Bli odkryte otwarcie jest twoj\u0105 ostatni\u0105 kart\u0105, wygrywasz natychmiast. Ostatnia karta zagrana zakryta wymaga zwyk\u0142ych reakcji."),
            rule_section(:sound, "D\u017Awi\u0119ki podczas gry",
              "Rozdaniu towarzyszy tasowanie, a przyj\u0119temu zagraniu odg\u0142os wyk\u0142adania kart, taki sam dla prawdy i blefu. Sprawdzenie ma osobny sygna\u0142, po kt\u00F3rym nast\u0119puj\u0105 odg\u0142osy odkrycia, rozstrzygni\u0119cia i zebrania stosu. Zwyk\u0142y sygna\u0142 decyzji wskazuje twoj\u0105 tur\u0119 lub reakcj\u0119, a efekty wyniku oznaczaj\u0105 koniec partii. Wa\u017Cne informacje s\u0105 tak\u017Ce wypowiadane, wi\u0119c mo\u017Cna gra\u0107 z wy\u0142\u0105czonymi opcjonalnymi efektami."),
            rule_section(:controls, "Skr\u00F3ty klawiszowe",
              "Enter: przygotuj i zatwierd\u017A bie\u017C\u0105c\u0105 kart\u0119 lub pakiet",
              "Shift+Enter: zaznacz lub odznacz bie\u017C\u0105c\u0105 kart\u0119, poza wariantem na kolor",
              "P: odczytaj przygotowany pakiet",
              "Shift+P: wyczy\u015B\u0107 przygotowany pakiet",
              "K: sprawd\u017A zagranie podczas swojej reakcji",
              "Spacja: odm\u00F3w sprawdzenia tego zagrania",
              "X: spasuj do ko\u0144ca stosu w Bluff",
              "H: odczytaj w\u0142asn\u0105 r\u0119k\u0119",
              "T: odczytaj, kto ma zagra\u0107 lub zareagowa\u0107",
              "S: odczytaj liczb\u0119 kart ka\u017Cdego gracza",
              "C: odczytaj jawny stan stosu i deklaracj\u0119",
              "Shift+C: sortuj wed\u0142ug koloru",
              "Shift+H: sortuj wed\u0142ug warto\u015Bci",
              "Shift+M: przywr\u00F3\u0107 kolejno\u015B\u0107 otrzymania kart",
              "Z: przejd\u017A do nast\u0119pnej mo\u017Cliwej karty bez zagrywania",
              "Shift+Z: przejd\u017A do poprzedniej mo\u017Cliwej karty bez zagrywania",
              "Escape: anuluj bie\u017C\u0105cy wyb\u00F3r")
          ]
        when "ru"
          [
            rule_section(:aim, "\u0426\u0435\u043B\u044C \u0438\u0433\u0440\u044B \u0438 \u0440\u0430\u0437\u0434\u0430\u0447\u0430",
              "\u0418\u0437\u0431\u0430\u0432\u044C\u0442\u0435\u0441\u044C \u043E\u0442 \u0432\u0441\u0435\u0445 \u043A\u0430\u0440\u0442 \u0440\u0430\u043D\u044C\u0448\u0435 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445. \u0412\u0441\u044F \u043A\u043E\u043B\u043E\u0434\u0430 \u0438\u0437 52 \u043A\u0430\u0440\u0442 \u0431\u0435\u0437 \u0434\u0436\u043E\u043A\u0435\u0440\u043E\u0432 \u0440\u0430\u0437\u0434\u0430\u0451\u0442\u0441\u044F \u043F\u043E \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u0438 \u043F\u043E\u0440\u043E\u0432\u043D\u0443 \u043C\u0435\u0436\u0434\u0443 2\u20138 \u0438\u0433\u0440\u043E\u043A\u0430\u043C\u0438. \u041F\u0435\u0440\u0432\u044B\u0439 \u0438\u0433\u0440\u043E\u043A \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442\u0441\u044F \u0436\u0435\u0440\u0435\u0431\u044C\u0451\u0432\u043A\u043E\u0439. \u0412\u044B \u0432\u0438\u0434\u0438\u0442\u0435 \u0441\u0432\u043E\u044E \u0440\u0443\u043A\u0443; \u043A\u043B\u0430\u0432\u0438\u0448\u0430 S \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u043A\u0430\u0440\u0442 \u0443 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u0430.",
              "\u0412 \u043E\u0431\u044B\u0447\u043D\u043E\u043C \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0435 \u0432\u044B \u043A\u043B\u0430\u0434\u0451\u0442\u0435 \u043E\u0442 \u043E\u0434\u043D\u043E\u0439 \u0434\u043E \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u043A\u0430\u0440\u0442 \u0440\u0443\u0431\u0430\u0448\u043A\u043E\u0439 \u0432\u0432\u0435\u0440\u0445 \u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442\u0435 \u0438\u0445 \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u043E. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u044E\u0442 \u0442\u0443\u0437\u043E\u0432, \u0437\u0430\u0442\u0435\u043C \u0434\u0432\u043E\u0435\u043A, \u0442\u0440\u043E\u0435\u043A \u0438 \u0434\u0430\u043B\u0435\u0435 \u0434\u043E \u0434\u0435\u0441\u044F\u0442\u043E\u043A, \u0432\u0430\u043B\u0435\u0442\u043E\u0432, \u0434\u0430\u043C \u0438 \u043A\u043E\u0440\u043E\u043B\u0435\u0439. \u041F\u043E\u0441\u043B\u0435 \u043A\u043E\u0440\u043E\u043B\u0435\u0439 \u0441\u043D\u043E\u0432\u0430 \u0438\u0434\u0443\u0442 \u0442\u0443\u0437\u044B. \u041D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u0435 \u043A\u0430\u0440\u0442\u044B \u043C\u043E\u0433\u0443\u0442 \u0431\u044B\u0442\u044C \u0434\u0440\u0443\u0433\u0438\u043C\u0438: \u0431\u043B\u0435\u0444 \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043D. \u041A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0432\u044B\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0445 \u043A\u0430\u0440\u0442 \u0432\u0441\u0435\u0433\u0434\u0430 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043F\u0440\u0430\u0432\u0434\u0438\u0432\u043E."),
            rule_section(:turn, "\u0412\u044B\u0431\u043E\u0440 \u0438 \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u043A\u0430\u0440\u0442",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438 \u0432\u0432\u0435\u0440\u0445 \u0438 \u0432\u043D\u0438\u0437 \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0430\u044E\u0442 \u043F\u043E \u0432\u0441\u0435\u0439 \u0440\u0443\u043A\u0435, \u0432\u043B\u0435\u0432\u043E \u0438 \u0432\u043F\u0440\u0430\u0432\u043E \u2014 \u043C\u0435\u0436\u0434\u0443 \u043C\u0430\u0441\u0442\u044F\u043C\u0438. H \u0447\u0438\u0442\u0430\u0435\u0442 \u0440\u0443\u043A\u0443 \u0432 \u0442\u0435\u043A\u0443\u0449\u0435\u043C \u043F\u043E\u0440\u044F\u0434\u043A\u0435 \u043E\u0442\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u044F. \u0412\u044B\u0431\u0438\u0440\u0430\u0442\u044C \u043C\u043E\u0436\u043D\u043E \u043B\u044E\u0431\u044B\u0435 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u043D\u0435 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044E.",
              "\u0427\u0442\u043E\u0431\u044B \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u0438\u0442\u044C \u043E\u0434\u043D\u0443 \u043A\u0430\u0440\u0442\u0443, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0435\u0451 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u0414\u043B\u044F \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u0438\u0445 \u043A\u0430\u0440\u0442 \u043E\u0442\u043C\u0435\u0447\u0430\u0439\u0442\u0435 \u0438\u0445 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435\u043C Shift+Enter; \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0435 \u043D\u0430\u0436\u0430\u0442\u0438\u0435 \u0441\u043D\u0438\u043C\u0430\u0435\u0442 \u043E\u0442\u043C\u0435\u0442\u043A\u0443. P \u0447\u0438\u0442\u0430\u0435\u0442 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B, Shift+P \u043E\u0447\u0438\u0449\u0430\u0435\u0442 \u0432\u044B\u0431\u043E\u0440. \u041F\u0440\u0438 \u043D\u0430\u0436\u0430\u0442\u0438\u0438 Enter \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0438 \u043A\u0430\u0440\u0442\u0430 \u043F\u043E\u0434 \u043A\u0443\u0440\u0441\u043E\u0440\u043E\u043C, \u0435\u0441\u043B\u0438 \u043E\u043D\u0430 \u0435\u0449\u0451 \u043D\u0435 \u043E\u0442\u043C\u0435\u0447\u0435\u043D\u0430. \u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u0438\u0442\u043E\u0433\u043E\u0432\u043E\u0435 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u0438 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0421\u044B\u0433\u0440\u0430\u0442\u044C. Escape \u0438\u043B\u0438 \u041E\u0442\u043C\u0435\u043D\u0430 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u043A \u0440\u0443\u043A\u0435 \u0431\u0435\u0437 \u0445\u043E\u0434\u0430 \u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B. \u0420\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u0442\u0430\u043A\u0436\u0435 \u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D \u0432 \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442\u043D\u043E\u043C \u043C\u0435\u043D\u044E \u0440\u0443\u043A\u0438.",
              "\u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043D\u0430 \u0445\u043E\u0434\u0435 \u0442\u0443\u0437\u043E\u0432 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0434\u0432\u0435 \u0440\u0430\u0437\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u0438 \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u0434\u0432\u0443\u0445 \u0442\u0443\u0437\u043E\u0432. \u0422\u0443\u0437\u0430\u043C\u0438 \u043C\u043E\u0433\u0443\u0442 \u043E\u043A\u0430\u0437\u0430\u0442\u044C\u0441\u044F \u043E\u0431\u0435 \u043A\u0430\u0440\u0442\u044B, \u043D\u0438 \u043E\u0434\u043D\u0430 \u0438\u043B\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0434\u043D\u0430. \u0421\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0438 \u0441\u043B\u044B\u0448\u0430\u0442 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u0438 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E, \u043D\u043E \u043D\u0435 \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u044F \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0445 \u043A\u0430\u0440\u0442. \u041F\u043E\u0441\u043B\u0435 \u0440\u0435\u0430\u043A\u0446\u0438\u0439 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0438\u0433\u0440\u043E\u043A \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442 \u0434\u0432\u043E\u0435\u043A, \u0434\u0430\u0436\u0435 \u0435\u0441\u043B\u0438 \u0432\u0430\u0448\u0438\u0445 \u0442\u0443\u0437\u043E\u0432 \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u043B\u0438."),
            rule_section(:reaction, "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F",
              "\u041F\u043E\u0441\u043B\u0435 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0433\u043E \u0445\u043E\u0434\u0430 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0438 \u0440\u0435\u0448\u0430\u044E\u0442 \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438, \u043D\u0430\u0447\u0438\u043D\u0430\u044F \u0441\u043E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u043C\u0435\u0441\u0442\u0430. \u041A\u043E\u0433\u0434\u0430 \u043D\u0430\u0441\u0442\u0443\u043F\u0438\u0442 \u0432\u0430\u0448\u0430 \u0440\u0435\u0430\u043A\u0446\u0438\u044F, K \u0438\u043B\u0438 \u043A\u043E\u043C\u0430\u043D\u0434\u0430 \u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u043E\u0441\u043F\u0430\u0440\u0438\u0432\u0430\u0435\u0442 \u0445\u043E\u0434. \u041F\u0440\u043E\u0431\u0435\u043B \u0438\u043B\u0438 \u041D\u0435 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u0442\u044C \u043F\u0435\u0440\u0435\u0434\u0430\u0451\u0442 \u0440\u0435\u0448\u0435\u043D\u0438\u0435 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C\u0443 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0443. \u041E\u0442\u043A\u0430\u0437 \u043E\u0442 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0438 \u043D\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442 \u043F\u0440\u0430\u0432\u0434\u0438\u0432\u043E\u0441\u0442\u044C \u043A\u0430\u0440\u0442 \u0438 \u043D\u0435 \u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043F\u0430\u0441\u043E\u043C \u0432 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0435 Bluff.",
              "\u0414\u043B\u044F \u0440\u0435\u0430\u043A\u0446\u0438\u0438 \u043D\u0435\u0442 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u044F \u0432\u0440\u0435\u043C\u0435\u043D\u0438. \u041F\u0430\u0443\u0437\u0430, \u0447\u0442\u0435\u043D\u0438\u0435 \u0441\u043F\u0440\u0430\u0432\u043A\u0438 \u0438\u043B\u0438 \u043E\u0442\u0445\u043E\u0434 \u043E\u0442 \u043A\u043B\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u044B \u043D\u0435 \u043E\u0437\u043D\u0430\u0447\u0430\u044E\u0442 \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u044F \u0441 \u0445\u043E\u0434\u043E\u043C. \u041E\u0442\u0432\u0435\u0447\u0430\u0435\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u044B\u0439 \u0438\u0433\u0440\u043E\u043A. \u041F\u0435\u0440\u0432\u0430\u044F \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0440\u0435\u0430\u043A\u0446\u0438\u0438. \u0415\u0441\u043B\u0438 \u043D\u0438\u043A\u0442\u043E \u043D\u0435 \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u043B, \u043A\u0430\u0440\u0442\u044B \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0432 \u0441\u0442\u043E\u043F\u043A\u0435 \u0438 \u0438\u0433\u0440\u0430 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442\u0441\u044F.",
              "\u041E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u044F\u044F \u0433\u0440\u0443\u043F\u043F\u0430 \u043A\u0430\u0440\u0442. \u0415\u0441\u043B\u0438 \u0445\u043E\u0442\u044F \u0431\u044B \u043E\u0434\u043D\u0430 \u043A\u0430\u0440\u0442\u0430 \u0434\u0440\u0443\u0433\u043E\u0433\u043E \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u0430, \u0432\u0441\u044E \u0441\u0442\u043E\u043F\u043A\u0443 \u0431\u0435\u0440\u0451\u0442 \u0430\u0432\u0442\u043E\u0440 \u0445\u043E\u0434\u0430. \u0415\u0441\u043B\u0438 \u0441\u043E\u0432\u043F\u0430\u0434\u0430\u044E\u0442 \u0432\u0441\u0435, \u0435\u0451 \u0431\u0435\u0440\u0451\u0442 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u044E\u0449\u0438\u0439. \u0411\u043E\u043B\u0435\u0435 \u0440\u0430\u043D\u043D\u0438\u0435 \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u043F\u0440\u0438 \u044D\u0442\u043E\u043C \u043D\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u044E\u0442\u0441\u044F. \u041F\u043E\u0441\u043B\u0435 \u043B\u044E\u0431\u043E\u0433\u043E \u0438\u0441\u0445\u043E\u0434\u0430 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043C\u0435\u0441\u0442 \u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432. C \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u0440\u0430\u0437\u043C\u0435\u0440 \u0441\u0442\u043E\u043F\u043A\u0438, \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u0438 \u043E\u0436\u0438\u0434\u0430\u0435\u043C\u043E\u0435 \u0440\u0435\u0448\u0435\u043D\u0438\u0435; T \u2014 \u043A\u0442\u043E \u0434\u043E\u043B\u0436\u0435\u043D \u0434\u0435\u0439\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C."),
            rule_section(:ending, "\u041F\u043E\u0431\u0435\u0434\u0430",
              "\u0420\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0445 \u043A\u0430\u0440\u0442 \u0435\u0449\u0451 \u043D\u0435 \u0434\u0430\u0451\u0442 \u043D\u0435\u043C\u0435\u0434\u043B\u0435\u043D\u043D\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u044B: \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442 \u043F\u0440\u0430\u0432\u043E \u0440\u0435\u0430\u043A\u0446\u0438\u0438. \u0412\u044B \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442\u0435, \u0435\u0441\u043B\u0438 \u0432\u0441\u0435 \u043F\u0440\u0438\u043D\u044F\u043B\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0445\u043E\u0434, \u0434\u0430\u0436\u0435 \u0435\u0441\u043B\u0438 \u044D\u0442\u043E \u0431\u044B\u043B \u0431\u043B\u0435\u0444. \u0412\u044B \u0442\u0430\u043A\u0436\u0435 \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442\u0435, \u0435\u0441\u043B\u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043B\u0430 \u043F\u0440\u0430\u0432\u0434\u0438\u0432\u043E\u0441\u0442\u044C \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u0433\u0440\u0443\u043F\u043F\u044B. \u0415\u0441\u043B\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0431\u043B\u0435\u0444 \u0440\u0430\u0441\u043A\u0440\u044B\u0442, \u0432\u044B \u0431\u0435\u0440\u0451\u0442\u0435 \u0441\u0442\u043E\u043F\u043A\u0443 \u0438 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442\u0435 \u0438\u0433\u0440\u0443. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u043E\u0434\u0438\u043D; \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u043C \u043D\u0435 \u043D\u0430\u0447\u0438\u0441\u043B\u044F\u044E\u0442\u0441\u044F \u043E\u0447\u043A\u0438 \u0438 \u043D\u0435 \u043F\u0440\u0438\u0441\u0432\u0430\u0438\u0432\u0430\u044E\u0442\u0441\u044F \u043C\u0435\u0441\u0442\u0430."),
            rule_section(:variants, "\u0412\u044B\u0431\u043E\u0440 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0430",
              "\u0412\u0430\u0440\u0438\u0430\u043D\u0442 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044F \u043F\u0440\u0438 \u0441\u043E\u0437\u0434\u0430\u043D\u0438\u0438 \u0441\u0442\u043E\u043B\u0430. \u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F \u041A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u0438\u0439: \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u0430 \u043F\u043E \u0432\u043E\u0437\u0440\u0430\u0441\u0442\u0430\u043D\u0438\u044E, \u043E\u043F\u0438\u0441\u0430\u043D\u043D\u044B\u0439 \u0432\u044B\u0448\u0435. \u0412\u043E \u0432\u0441\u0435\u0445 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0430\u0445 \u043E\u0434\u043D\u0430 \u043A\u043E\u043B\u043E\u0434\u0430 \u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0440\u0435\u0430\u043A\u0446\u0438\u0438 \u0431\u0435\u0437 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u044F \u0432\u0440\u0435\u043C\u0435\u043D\u0438.",
              "- \u0414\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u0430 \u043F\u043E \u0443\u0431\u044B\u0432\u0430\u043D\u0438\u044E: \u043F\u043E\u0441\u043B\u0435 \u0442\u0443\u0437\u043E\u0432 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u044E\u0442 \u043A\u043E\u0440\u043E\u043B\u0435\u0439, \u0434\u0430\u043C, \u0432\u0430\u043B\u0435\u0442\u043E\u0432, \u0434\u0435\u0441\u044F\u0442\u043E\u043A \u0438 \u0434\u0430\u043B\u0435\u0435 \u0434\u043E \u0434\u0432\u043E\u0435\u043A, \u0437\u0430\u0442\u0435\u043C \u0441\u043D\u043E\u0432\u0430 \u0442\u0443\u0437\u043E\u0432. \u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u043D\u0435 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C \u0437\u0430\u043D\u043E\u0432\u043E.",
              "- \u0422\u043E \u0436\u0435 \u0438\u043B\u0438 \u0441\u043E\u0441\u0435\u0434\u043D\u0435\u0435 \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u043E: \u043F\u0435\u0440\u0432\u043E\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u2014 \u0442\u0443\u0437\u044B. \u0417\u0430\u0442\u0435\u043C \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0435\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043D\u043E\u0435 \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u043E \u0438\u043B\u0438 \u0441\u043E\u0441\u0435\u0434\u043D\u0435\u0435 \u0441 \u043D\u0438\u043C. \u041F\u043E\u0441\u043B\u0435 \u0441\u0435\u043C\u0451\u0440\u043E\u043A \u043C\u043E\u0436\u043D\u043E \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u0448\u0435\u0441\u0442\u0451\u0440\u043E\u043A, \u0441\u0435\u043C\u0451\u0440\u043E\u043A \u0438\u043B\u0438 \u0432\u043E\u0441\u044C\u043C\u0451\u0440\u043E\u043A; \u043F\u043E\u0441\u043B\u0435 \u0442\u0443\u0437\u043E\u0432 \u2014 \u043A\u043E\u0440\u043E\u043B\u0435\u0439, \u0442\u0443\u0437\u043E\u0432 \u0438\u043B\u0438 \u0434\u0432\u043E\u0435\u043A. \u0412 \u044D\u0442\u043E\u0439 \u0432\u0435\u0440\u0441\u0438\u0438 \u043A\u043E\u0440\u043E\u043B\u044C \u0438 \u0442\u0443\u0437 \u0441\u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F \u0441\u043E\u0441\u0435\u0434\u043D\u0438\u043C\u0438. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u0432 \u043E\u043A\u043D\u0435 \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u044F \u043A\u0430\u0440\u0442 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 \u0421\u044B\u0433\u0440\u0430\u0442\u044C, \u0447\u0442\u043E\u0431\u044B \u043E\u0442\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u0435\u0433\u043E \u0432\u043C\u0435\u0441\u0442\u0435 \u0441 \u043A\u0430\u0440\u0442\u0430\u043C\u0438.",
              "- Bluff: \u043F\u043E\u0441\u0442\u043E\u044F\u043D\u043D\u043E\u0435 \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u043E \u0441\u0442\u043E\u043F\u043A\u0438 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u0430\u043D \u043D\u0430 3\u20136 \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u0438 \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u043F\u0430\u0441, \u043E\u043F\u0438\u0441\u0430\u043D\u043D\u044B\u0439 \u043D\u0438\u0436\u0435.",
              "- \u041C\u0430\u0441\u0442\u044C: \u043E\u0434\u0438\u043D\u043E\u0447\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0441 \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u0439 \u043A\u0430\u0440\u0442\u044B, \u043F\u043E\u0441\u043B\u0435 \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u043A\u043B\u0430\u0434\u0443\u0442 \u043F\u043E \u043E\u0434\u043D\u043E\u0439 \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0439."),
            rule_section(:bluff, "Bluff: \u043E\u0434\u043D\u043E \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u043E \u0434\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u0438\u044F \u0441\u0442\u043E\u043F\u043A\u0438",
              "\u041E\u0442\u043A\u0440\u044B\u0432\u0430\u044E\u0449\u0438\u0439 \u043A\u043B\u0430\u0434\u0451\u0442 \u043E\u0442 \u043E\u0434\u043D\u043E\u0439 \u0434\u043E \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u043A\u0430\u0440\u0442 \u0438 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u0432 \u0434\u0438\u0430\u043B\u043E\u0433\u0435 \u043B\u044E\u0431\u043E\u0435 \u0438\u0437 \u0442\u0440\u0438\u043D\u0430\u0434\u0446\u0430\u0442\u0438 \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432. \u041E\u043D\u043E \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0434\u043B\u044F \u0432\u0441\u0435\u0445 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0445 \u0433\u0440\u0443\u043F\u043F \u0432 \u044D\u0442\u043E\u0439 \u0441\u0442\u043E\u043F\u043A\u0435. \u0412 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434 \u043C\u043E\u0436\u043D\u043E \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u043E\u0442 \u043E\u0434\u043D\u043E\u0439 \u0434\u043E \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u043A\u0430\u0440\u0442 \u0438\u043B\u0438 \u043D\u0430\u0436\u0430\u0442\u044C X, \u0447\u0442\u043E\u0431\u044B \u043F\u0430\u0441\u043E\u0432\u0430\u0442\u044C \u0434\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u0438\u044F \u0441\u0442\u043E\u043F\u043A\u0438. \u041E\u0442\u043A\u0440\u044B\u0442\u044C \u043F\u0443\u0441\u0442\u0443\u044E \u0441\u0442\u043E\u043F\u043A\u0443 \u043F\u0430\u0441\u043E\u043C \u043D\u0435\u043B\u044C\u0437\u044F.",
              "\u041F\u043E\u0441\u043B\u0435 \u043F\u0430\u0441\u0430 \u0432\u044B \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442\u0435 \u043A\u0430\u0440\u0442\u044B \u0432 \u044D\u0442\u0443 \u0441\u0442\u043E\u043F\u043A\u0443, \u043D\u043E \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u043C\u043E\u0436\u0435\u0442\u0435 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u0442\u044C \u043A\u0430\u0436\u0434\u0443\u044E \u043D\u043E\u0432\u0443\u044E \u0433\u0440\u0443\u043F\u043F\u0443. \u041D\u043E\u0432\u043E\u0435 \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u0435 \u043D\u0435 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u043F\u0440\u0430\u0432\u043E \u0445\u043E\u0434\u0430 \u0442\u0435\u043C, \u043A\u0442\u043E \u0443\u0436\u0435 \u043F\u0430\u0441\u043E\u0432\u0430\u043B. \u0415\u0441\u043B\u0438 \u0431\u0435\u0437 \u043F\u0430\u0441\u0430 \u043E\u0441\u0442\u0430\u043B\u0441\u044F \u043E\u0434\u0438\u043D \u0438\u0433\u0440\u043E\u043A, \u043E\u043D \u043C\u043E\u0436\u0435\u0442 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0442\u044C \u0433\u0440\u0443\u043F\u043F\u044B \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E; \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043A\u0430\u0436\u0434\u044B\u0439 \u0440\u0430\u0437 \u0440\u0435\u0448\u0430\u044E\u0442, \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u0442\u044C \u043B\u0438 \u043D\u043E\u0432\u043E\u0435 \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u0435.",
              "\u041A\u043E\u0433\u0434\u0430 \u043F\u0430\u0441\u043E\u0432\u0430\u043B\u0438 \u0432\u0441\u0435, \u0441\u0442\u043E\u043F\u043A\u0443 \u0443\u0431\u0438\u0440\u0430\u044E\u0442 \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0439 \u0438\u0437 \u043F\u0430\u0440\u0442\u0438\u0438, \u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0432\u044B\u043B\u043E\u0436\u0438\u0432\u0448\u0438\u0439 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u043D\u043E\u0432\u0443\u044E \u0441 \u043B\u044E\u0431\u044B\u043C \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u043E\u043C. \u041F\u043E\u0441\u043B\u0435 \u0432\u0435\u0440\u043D\u043E\u0439 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0438 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u044E\u0449\u0438\u0439, \u043F\u043E\u0441\u043B\u0435 \u043E\u0448\u0438\u0431\u043E\u0447\u043D\u043E\u0439 \u2014 \u0430\u0432\u0442\u043E\u0440 \u043F\u0440\u043E\u0432\u0435\u0440\u0435\u043D\u043D\u043E\u0433\u043E \u0445\u043E\u0434\u0430. \u041F\u0430\u0441\u044B \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u044E\u0442\u0441\u044F. \u041F\u043E\u0441\u043B\u0435\u0434\u043D\u044F\u044F \u0433\u0440\u0443\u043F\u043F\u0430 \u0442\u0430\u043A\u0436\u0435 \u0434\u043E\u043B\u0436\u043D\u0430 \u043F\u0440\u043E\u0439\u0442\u0438 \u0440\u0435\u0430\u043A\u0446\u0438\u0438, \u043F\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043C \u0435\u0451 \u0430\u0432\u0442\u043E\u0440 \u043F\u043E\u0431\u0435\u0434\u0438\u0442. \u0412 \u044D\u0442\u043E\u0439 \u0432\u0435\u0440\u0441\u0438\u0438 \u0440\u0430\u0437\u0434\u0430\u0451\u0442\u0441\u044F \u0432\u0441\u044F \u043A\u043E\u043B\u043E\u0434\u0430, \u0431\u0435\u0437 \u0434\u0436\u043E\u043A\u0435\u0440\u043E\u0432 \u0438 \u043F\u0440\u0430\u0432\u0438\u043B Force."),
            rule_section(:suit, "\u041C\u0430\u0441\u0442\u044C: \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u0435 \u043D\u0430\u0447\u0430\u043B\u043E \u0441\u0442\u043E\u043F\u043A\u0438",
              "\u041E\u0442\u043A\u0440\u044B\u0432\u0430\u044E\u0449\u0438\u0439 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u043A\u0430\u0440\u0442\u0443 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442 \u0435\u0451 \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0439 \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Enter. \u041D\u0430\u0441\u0442\u043E\u044F\u0449\u0430\u044F \u043C\u0430\u0441\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u0437\u0430\u0434\u0430\u0451\u0442 \u043C\u0430\u0441\u0442\u044C \u0441\u0442\u043E\u043F\u043A\u0438. \u041F\u0440\u043E\u0432\u0435\u0440\u044F\u0442\u044C \u044D\u0442\u0443 \u0432\u0438\u0434\u0438\u043C\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u043D\u0435\u043B\u044C\u0437\u044F. \u0421\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u0438\u0433\u0440\u043E\u043A\u0438 \u043A\u043B\u0430\u0434\u0443\u0442 \u043F\u043E \u043E\u0434\u043D\u043E\u0439 \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0439 \u043A\u0430\u0440\u0442\u0435, \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u044F \u0442\u0443 \u0436\u0435 \u043C\u0430\u0441\u0442\u044C, \u0431\u0435\u0437 \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u0430. Shift+Enter \u0437\u0434\u0435\u0441\u044C \u043D\u0435 \u0441\u043E\u0431\u0438\u0440\u0430\u0435\u0442 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043A\u0430\u0440\u0442.",
              "\u041F\u0440\u0438 \u0440\u0435\u0430\u043A\u0446\u0438\u0438 \u043D\u0430 \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0439 \u0445\u043E\u0434 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439\u0442\u0435 K \u0438\u043B\u0438 \u041F\u0440\u043E\u0431\u0435\u043B. \u041F\u0440\u043E\u0432\u0435\u0440\u044F\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043C\u0430\u0441\u0442\u044C: \u0441\u0435\u043C\u0451\u0440\u043A\u0430 \u0438 \u043A\u043E\u0440\u043E\u043B\u044C \u0447\u0435\u0440\u0432\u0435\u0439 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u043E \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0442 \u043A \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043D\u044B\u043C \u0447\u0435\u0440\u0432\u044F\u043C. \u041F\u0440\u0438 \u043D\u0435\u0432\u0435\u0440\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438 \u0441\u0442\u043E\u043F\u043A\u0443 \u0431\u0435\u0440\u0451\u0442 \u0430\u0432\u0442\u043E\u0440, \u043F\u0440\u0438 \u0432\u0435\u0440\u043D\u043E\u0439 \u2014 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u044E\u0449\u0438\u0439. \u0417\u0430\u0431\u0440\u0430\u0432\u0448\u0438\u0439 \u0441\u0442\u043E\u043F\u043A\u0443 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u043B\u044E\u0431\u043E\u0439 \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u0439 \u043A\u0430\u0440\u0442\u043E\u0439. \u0415\u0441\u043B\u0438 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u044E\u0449\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u0431\u044B\u043B\u0430 \u0432\u0430\u0448\u0435\u0439 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439, \u0432\u044B \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442\u0435 \u0441\u0440\u0430\u0437\u0443. \u041F\u043E\u0441\u043B\u0435\u0434\u043D\u044F\u044F \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043E\u0431\u044B\u0447\u043D\u044B\u0445 \u0440\u0435\u0430\u043A\u0446\u0438\u0439."),
            rule_section(:sound, "\u0417\u0432\u0443\u043A\u0438 \u0438\u0433\u0440\u044B",
              "\u0420\u0430\u0437\u0434\u0430\u0447\u0443 \u0441\u043E\u043F\u0440\u043E\u0432\u043E\u0436\u0434\u0430\u0435\u0442 \u0437\u0432\u0443\u043A \u0442\u0430\u0441\u043E\u0432\u0430\u043D\u0438\u044F, \u0430 \u043F\u0440\u0438\u043D\u044F\u0442\u044B\u0439 \u0445\u043E\u0434 \u2014 \u0437\u0432\u0443\u043A \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u044F \u043A\u0430\u0440\u0442, \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0439 \u0434\u043B\u044F \u043F\u0440\u0430\u0432\u0434\u044B \u0438 \u0431\u043B\u0435\u0444\u0430. \u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u043E\u0442\u043C\u0435\u0447\u0430\u0435\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u043C \u0441\u0438\u0433\u043D\u0430\u043B\u043E\u043C, \u0437\u0430\u0442\u0435\u043C \u0441\u043B\u044B\u0448\u043D\u044B \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u0435, \u0438\u0441\u0445\u043E\u0434 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0438 \u0438 \u0441\u0431\u043E\u0440 \u043A\u0430\u0440\u0442. \u041E\u0431\u044B\u0447\u043D\u044B\u0439 \u0441\u0438\u0433\u043D\u0430\u043B \u0440\u0435\u0448\u0435\u043D\u0438\u044F \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u043E \u0432\u0430\u0448\u0435\u043C \u0445\u043E\u0434\u0435 \u0438\u043B\u0438 \u0440\u0435\u0430\u043A\u0446\u0438\u0438, \u0430 \u0441\u0438\u0433\u043D\u0430\u043B\u044B \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430 \u2014 \u043E \u043A\u043E\u043D\u0446\u0435 \u043F\u0430\u0440\u0442\u0438\u0438. \u0412\u0430\u0436\u043D\u044B\u0435 \u0441\u0432\u0435\u0434\u0435\u043D\u0438\u044F \u0442\u0430\u043A\u0436\u0435 \u043F\u0440\u043E\u0438\u0437\u043D\u043E\u0441\u044F\u0442\u0441\u044F, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043C\u043E\u0436\u043D\u043E \u0438\u0433\u0440\u0430\u0442\u044C \u0441 \u0432\u044B\u043A\u043B\u044E\u0447\u0435\u043D\u043D\u044B\u043C\u0438 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u043C\u0438 \u044D\u0444\u0444\u0435\u043A\u0442\u0430\u043C\u0438."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0448\u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F",
              "Enter: \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u0438\u0442\u044C \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u043A\u0430\u0440\u0442\u0443 \u0438\u043B\u0438 \u0433\u0440\u0443\u043F\u043F\u0443",
              "Shift+Enter: \u043E\u0442\u043C\u0435\u0442\u0438\u0442\u044C \u043A\u0430\u0440\u0442\u0443 \u0438\u043B\u0438 \u0441\u043D\u044F\u0442\u044C \u043E\u0442\u043C\u0435\u0442\u043A\u0443, \u043A\u0440\u043E\u043C\u0435 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0430 \u041C\u0430\u0441\u0442\u044C",
              "P: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B",
              "Shift+P: \u043E\u0447\u0438\u0441\u0442\u0438\u0442\u044C \u0432\u044B\u0431\u043E\u0440 \u043A\u0430\u0440\u0442",
              "K: \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u0445\u043E\u0434 \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u0441\u0432\u043E\u0435\u0439 \u0440\u0435\u0430\u043A\u0446\u0438\u0438",
